text:
/* Preserve the existing motion cascade above shared native button rules. */
html .appearance-control .appearance-menu .appearance-grid button {
  transform: none;
  filter: none;
  transition:
    background-color 180ms ease,
    border-color 180ms ease,
    transform 180ms cubic-bezier(0.2, 0.8, 0.2, 1);
}
.appearance-preview {
  --preview-bg: var(--color-appearance-control-preview-bg-2);
  --preview-ink: var(--color-appearance-control-preview-ink-3);
  --preview-accent: var(--color-appearance-control-preview-accent-4);
}
.appearance-preview-purple-dark {
  --preview-bg: var(--color-appearance-control-preview-bg-6);
  --preview-ink: var(--color-appearance-control-preview-ink-7);
  --preview-accent: var(--color-appearance-control-preview-accent-8);
}
.appearance-preview-vercel-light {
  --preview-bg: var(--color-appearance-control-preview-bg-9);
  --preview-ink: var(--color-appearance-control-preview-ink-10);
  --preview-accent: var(--color-appearance-control-preview-accent-11);
}
.appearance-preview-vercel-dark {
  --preview-bg: var(--color-appearance-control-preview-bg-12);
  --preview-ink: var(--color-appearance-control-preview-ink-13);
  --preview-accent: var(--color-appearance-control-preview-accent-14);
}

@media (prefers-reduced-motion: no-preference) {
  .appearance-menu {
    transform-origin: top right;
    animation: appearance-menu-enter 200ms cubic-bezier(0.2, 0.8, 0.2, 1);
  }
  .appearance-trigger > svg {
    transition: transform 200ms ease;
  }
  .appearance-trigger[aria-expanded="true"] > svg {
    transform: rotate(-12deg);
  }
  html .appearance-control .appearance-menu .appearance-grid button:hover {
    transform: translateY(-2px);
  }
  html .appearance-control .appearance-menu .appearance-grid button:active {
    transform: scale(0.98);
  }
  .appearance-check {
    animation: appearance-check-enter 180ms ease-out;
  }
  html[data-appearance-transition]::view-transition-old(root) {
    z-index: 2;
    animation: appearance-theme-out 200ms ease-out both;
  }
  html[data-appearance-transition]::view-transition-new(root) {
    z-index: 1;
    animation: none;
  }
  html[data-appearance-transition]::view-transition-group(root) {
    animation: none;
  }
}
@keyframes appearance-menu-enter {
  from {
    opacity: 0;
    transform: translateY(-6px) scale(0.97);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}
@keyframes appearance-check-enter {
  from {
    opacity: 0;
    transform: scale(0.7);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}
@keyframes appearance-theme-out {
  from {
    opacity: 1;
  }
  to {
    opacity: 0;
  }
}
